INSERT INTO src_locator(source_work_id,source_artifact_id,locator_type,heading_path,display_citation) SELECT artifact.source_work_id,artifact.source_artifact_id,'heading','Environments and Hazards > Weather',CASE work.work_code WHEN 'cepheus-engine.ogn' THEN 'Cepheus Engine SRD, Environments and Hazards: Weather' ELSE 'Cepheus Engine v9.1, Environments and Hazards: Weather' END FROM src_artifact artifact JOIN src_work work USING(source_work_id) WHERE artifact.source_uri IN('src/book3/environments-and-hazards.md','https://cepheus-srd.opengamingnetwork.com/cepheus-engine-srd/cepheus-engine-environments-and-hazards/') ON CONFLICT DO NOTHING;
WITH package AS(SELECT content_package_id FROM sys_content_package WHERE package_code='cepheus-engine') INSERT INTO rule_rule(content_package_id,rule_code,name,rule_category,rule_status,description) SELECT content_package_id,'environment.weather','Weather','other','approved','Severe weather applies separate -1 ranged modifiers for visibility and interference; sensors may avoid visibility only; extreme wind and rain apply -1 through -4 to all skill checks.' FROM package;
CREATE TABLE rule_weather_effect(rule_id bigint PRIMARY KEY REFERENCES rule_rule(rule_id),visibility_ranged_attack_dm smallint NOT NULL CHECK(visibility_ranged_attack_dm=-1),interference_ranged_attack_dm smallint NOT NULL CHECK(interference_ranged_attack_dm=-1),sensors_avoid_visibility boolean NOT NULL CHECK(sensors_avoid_visibility),sensors_avoid_interference boolean NOT NULL CHECK(NOT sensors_avoid_interference),extreme_skill_dm_max smallint NOT NULL CHECK(extreme_skill_dm_max=-1),extreme_skill_dm_min smallint NOT NULL CHECK(extreme_skill_dm_min=-4),visibility_condition_rule_id bigint NOT NULL REFERENCES rule_personal_battlefield_condition(rule_id),interference_condition_rule_id bigint NOT NULL REFERENCES rule_personal_battlefield_condition(rule_id));
INSERT INTO rule_weather_effect SELECT weather.rule_id,-1,-1,true,false,-1,-4,visibility.rule_id,interference.rule_id FROM rule_rule weather CROSS JOIN rule_personal_battlefield_condition visibility CROSS JOIN rule_personal_battlefield_condition interference WHERE weather.rule_code='environment.weather' AND visibility.condition_code='extreme-weather-visibility' AND interference.condition_code='extreme-weather-interference';
INSERT INTO src_record_provenance(rule_id,content_package_id,source_locator_id,provenance_class,is_primary_citation) SELECT rule.rule_id,rule.content_package_id,locator.source_locator_id,CASE work.work_code WHEN 'cepheus-engine.ogn' THEN 'direct' ELSE 'corroborating' END,work.work_code='cepheus-engine.ogn' FROM rule_rule rule CROSS JOIN src_locator locator JOIN src_work work USING(source_work_id) WHERE rule.rule_code='environment.weather' AND locator.heading_path='Environments and Hazards > Weather' AND work.work_code IN('cepheus-engine.ogn','cepheus-engine.github-v9.1');
CREATE TABLE env_weather_observation(weather_observation_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),location_id bigint REFERENCES loc_location(location_id),encounter_id bigint REFERENCES enc_encounter(encounter_id),visibility_penalty_active boolean NOT NULL,interference_penalty_active boolean NOT NULL,extreme_skill_dm smallint CHECK(extreme_skill_dm BETWEEN -4 AND -1),campaign_day bigint NOT NULL,campaign_second integer NOT NULL CHECK(campaign_second BETWEEN 0 AND 86399),observer_reference text NOT NULL CHECK(btrim(observer_reference)<>''),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(num_nonnulls(location_id,encounter_id)<=1));
CREATE TABLE env_weather_task_modifier_receipt(weather_task_modifier_receipt_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,weather_observation_id bigint NOT NULL REFERENCES env_weather_observation(weather_observation_id),task_command_id bigint NOT NULL UNIQUE REFERENCES cmd_actor_task_receipt(command_id),weather_modifier smallint NOT NULL CHECK(weather_modifier BETWEEN -4 AND -1),other_circumstance_modifier smallint NOT NULL,total_circumstance_modifier smallint NOT NULL,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(total_circumstance_modifier=weather_modifier+other_circumstance_modifier));
CREATE FUNCTION env_validate_weather_observation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.encounter_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM enc_encounter WHERE encounter_id=NEW.encounter_id AND campaign_id=NEW.campaign_id) THEN RAISE EXCEPTION 'Weather encounter must belong to observation campaign' USING ERRCODE='23514';END IF;RETURN NEW;END $$;CREATE TRIGGER env_weather_observation_valid BEFORE INSERT ON env_weather_observation FOR EACH ROW EXECUTE FUNCTION env_validate_weather_observation();
CREATE FUNCTION env_validate_weather_task_modifier() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE observation env_weather_observation%ROWTYPE;task cmd_actor_task_receipt%ROWTYPE;actor_campaign bigint;BEGIN SELECT * INTO STRICT observation FROM env_weather_observation WHERE weather_observation_id=NEW.weather_observation_id;SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id;SELECT campaign_id INTO STRICT actor_campaign FROM actor_actor WHERE actor_id=task.actor_id;IF observation.campaign_id<>actor_campaign OR observation.extreme_skill_dm IS NULL OR NEW.weather_modifier<>observation.extreme_skill_dm OR NEW.total_circumstance_modifier<>task.circumstance_modifier THEN RAISE EXCEPTION 'Weather task receipt must match actor campaign, observed extreme DM, and task circumstance total' USING ERRCODE='23514';END IF;RETURN NEW;END $$;CREATE TRIGGER env_weather_task_modifier_valid BEFORE INSERT ON env_weather_task_modifier_receipt FOR EACH ROW EXECUTE FUNCTION env_validate_weather_task_modifier();
CREATE FUNCTION env_reject_weather_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Weather observations and task modifier receipts are immutable';END $$;CREATE TRIGGER env_weather_observation_immutable BEFORE UPDATE OR DELETE ON env_weather_observation FOR EACH ROW EXECUTE FUNCTION env_reject_weather_history_mutation();CREATE TRIGGER env_weather_task_modifier_immutable BEFORE UPDATE OR DELETE ON env_weather_task_modifier_receipt FOR EACH ROW EXECUTE FUNCTION env_reject_weather_history_mutation();
